code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full horizontal bars encode a periodic row sequence.
    bars = {r: row[0] for r, row in enumerate(grid) if row and all(v == row[0] and v != 0 for v in row)}
    if bars:
        period = len(bars)
        seq = {r % period: color for r, color in bars.items()}
        return [[seq[r % period] for _ in range(w)] for r in range(h)]

    # Parallel down-right diagonal bars encode a periodic sequence over c-r.
    lanes = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in lanes and lanes[d] != color:
                    raise ValueError("inconsistent diagonal lane")
                lanes[d] = color
    period = len(lanes)
    seq = {d % period: color for d, color in lanes.items()}
    return [[seq[(c - r) % period] for c in range(w)] for r in range(h)]
'''
